) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `apartment` (`area`, `amenities`, `host_phone`, `city`, `description`, `review_count`, `rules`, `title`, `price_per_night_egp`, `bathrooms`, `photos`, `is_verified`, `discount_views`, `capacity`, `bedrooms`, `avg_rating`, `commission_rate`, `min_nights`, `host_name`, `is_featured`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('El Kawther', '["WiFi 50Mbps","AC","Full Kitchen","Washing Machine","Balcony","Smart TV","Hot Water"]', '+201001239876', 'hurghada', 'Clean, modern 2-bedroom apartment in El Kawther district. 5 minutes walk to the beach. Full kitchen, AC in all rooms, WiFi 50 Mbps, washing machine, balcony. Perfect for families or digital nomads. Walking distance to Senzo Mall and Al Ezaby Pharmacy.', 89, 'No smoking. No loud music after 11pm. Check-in 2pm, checkout 12pm.', 'Modern 2BR Apartment — El Kawther, Hurghada', 1200, 1, '[]', 1, 0, 4, 2, 4.7, 10, 3, 'Amira Khalil', 1, 'approved', '69d7d54f12e4eaaa47d2e64c', '2026-04-09 16:35:27', '2026-04-09 16:35:27', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `apartment` (`area`, `amenities`, `host_phone`, `city`, `description`, `review_count`, `rules`, `title`, `price_per_night_egp`, `bathrooms`, `photos`, `is_verified`, `discount_views`, `capacity`, `bedrooms`, `avg_rating`, `commission_rate`, `min_nights`, `host_name`, `is_featured`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('El Mamsha (Marina)', '["Sea View","Pool Access","WiFi","AC","Kitchenette","Smart TV"]', '+201112340099', 'hurghada', 'Cozy studio apartment with direct sea view on the Marina promenade. 10th floor, panoramic Red Sea views. Pool access. AC, WiFi, kitchenette. Perfect for couples. 5-minute walk to Marina restaurants and Jasmin Dive Center.', 56, 'Couples only. No parties. Smart casual in lobby.', 'Sea View Studio — Marina Hurghada', 1600, 1, '[]', 1, 0, 2, 1, 4.8, 10, 4, 'Mohamed Yasser', 0, 'approved', '69d7d54f12e4eaaa47d2e64d', '2026-04-09 16:35:27', '2026-04-09 16:35:27', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);

