-- ============================================================
-- Table: guide
-- ============================================================

CREATE TABLE IF NOT EXISTS `guide` (
  `id` VARCHAR(100) NOT NULL,
  `languages` TEXT NULL,
  `years_experience` INT NULL,
  `city` VARCHAR(100) NULL,
  `tour_types` TEXT NULL,
  `description` TEXT NULL,
  `review_count` INT NULL,
  `price_full_day` INT NULL,
  `is_verified` TINYINT(1) NULL,
  `specialties` TEXT NULL,
  `full_name` VARCHAR(255) NULL,
  `license_id` VARCHAR(100) NULL,
  `cities_covered` TEXT NULL,
  `avg_rating` DECIMAL(3,2) NULL,
  `photo_url` TEXT NULL,
  `price_half_day` INT NULL,
  `phone_whatsapp` VARCHAR(50) NULL,
  `status` VARCHAR(50) NULL,
  `created_date` DATETIME NULL,
  `updated_date` DATETIME NULL,
  `created_by_id` VARCHAR(100) NULL,
  `created_by` VARCHAR(255) NULL,
  `is_sample` TINYINT(1) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `guide` (`languages`, `years_experience`, `city`, `tour_types`, `description`, `review_count`, `price_full_day`, `is_verified`, `specialties`, `full_name`, `license_id`, `cities_covered`, `avg_rating`, `photo_url`, `price_half_day`, `phone_whatsapp`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('["English","Polish","German","Arabic"]', 10, 'hurghada', '["Red Sea Diving","Desert Safari","Giftun Island","Luxor day trips from Hurghada"]', 'Licensed both as a tourist guide AND a PADI Divemaster. Can combine diving knowledge with historical sites. 10 years experience. Speaks Polish — in high demand with Polish charter groups. Arranges Luxor day trips from Hurghada (3h drive).', 430, 1300, 1, '["Red Sea marine life","Desert ecology","Combined dive+culture tours","Polish-speaking groups"]', 'Tarek Hussein Abaza', 'EGY-GUIDE-4415', '["hurghada","luxor","cairo"]', 4.7, NULL, 750, '+201345098761', 'approved', '69d7d4da12e4eaaa47d2e618', '2026-04-09 16:33:30', '2026-04-09 16:33:30', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);

-- ============================================================
-- Table: hidden_gem_place
-- ============================================================

CREATE TABLE IF NOT EXISTS `hidden_gem_place` (
  `id` VARCHAR(100) NOT NULL,
  `area` VARCHAR(255) NULL,
  `keywords` TEXT NULL,
  `city` VARCHAR(100) NULL,
  `image_url` TEXT NULL,
  `main_image` TEXT NULL,
  `is_published` TINYINT(1) NULL,
  `description` TEXT NULL,
  `title` VARCHAR(255) NULL,
  `gem_number` INT NULL,
  `photos` TEXT NULL,
  `why_special` TEXT NULL,
  `tag` VARCHAR(100) NULL,
  `region` VARCHAR(100) NULL,
  `created_date` DATETIME NULL,
  `updated_date` DATETIME NULL,
  `created_by_id` VARCHAR(100) NULL,
  `created_by` VARCHAR(255) NULL,
  `is_sample` TINYINT(1) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `hidden_gem_place` (`area`, `keywords`, `city`, `image_url`, `main_image`, `is_published`, `description`, `title`, `gem_number`, `photos`, `why_special`, `tag`, `region`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Eastern Desert', 'hidden gems egypt travel explore must visit', 'Hurghada', 'https://images.unsplash.com/photo-1530053969600-caed2596d242?w=800&q=80', 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/5b5b0e05c_WadiBelli.jpg', 1, 'A rare combination of desert landscapes and hidden sea lagoons.', 'Wadi Belli', 24, '[]', 'Drive through golden mountains and suddenly arrive at a secret turquoise cove.', 'Explorer', 'Red Sea', '69e1504a058e34280fdabd0b', '2026-04-16 21:10:34', '2026-04-18 22:38:19', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `hidden_gem_place` (`area`, `keywords`, `city`, `image_url`, `main_image`, `is_published`, `description`, `title`, `gem_number`, `photos`, `why_special`, `tag`, `region`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Red Sea', 'hidden gems egypt travel explore must visit', 'Marsa Alam', 'https://images.unsplash.com/photo-1519046904884-53103b34b206?w=800&q=80', 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/fef353f7f_SharmElLuliv.jpg', 1, 'One of Egypt\'s most pristine beaches — no resorts, no umbrellas.', 'Sharm El Luli', 20, '["https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/d0908de25_SharmElLuli.jfif"]', 'Crystal-clear water, white sand, and zero commercialization. Pure paradise.', 'Chill', 'Red Sea', '69e1504a058e34280fdabd07', '2026-04-16 21:10:34', '2026-04-18 22:04:48', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `hidden_gem_place` (`area`, `keywords`, `city`, `image_url`, `main_image`, `is_published`, `description`, `title`, `gem_number`, `photos`, `why_special`, `tag`, `region`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Lagoon', 'hidden gems egypt travel explore must visit', 'El Gouna', 'https://images.unsplash.com/photo-1530655638484-de9b8e49f8a2?w=800&q=80', 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/98798dbb0_Screenshot2026-04-19005127.png', 1, 'Energetic wakeboarding cable park with a strong local youth scene.', 'Sliders Cable Park', 28, '["https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/3034636a8_Screenshot2026-04-19005127.png"]', 'Not just a sport — it\'s a whole social world that most tourists never discover.', 'Adventure', 'El Gouna', '69e1504a058e34280fdabd0f', '2026-04-16 21:10:34', '2026-04-18 22:52:09', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `hidden_gem_place` (`area`, `keywords`, `city`, `image_url`, `main_image`, `is_published`, `description`, `title`, `gem_number`, `photos`, `why_special`, `tag`, `region`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('South Sinai', 'hidden gems egypt travel explore must visit', 'Nuweiba', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=80', 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/aba12ca40_Screenshot2026-04-18235110.png', 1, 'Simple beach huts, bonfires, and complete silence on the Gulf of Aqaba.', 'Nuweiba Tarabin Area', 17, '["https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/9b7facf4f_Sunset_in_the_bosom_of_the_mountain_in_nueiba.jpg"]', 'The most off-grid beach experience possible — no noise, no Wi-Fi, no agenda.', 'Chill', 'Sinai', '69e1504a058e34280fdabd04', '2026-04-16 21:10:34', '2026-04-18 21:52:12', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
