-- ============================================================
-- Table: listing
-- ============================================================

CREATE TABLE IF NOT EXISTS `listing` (
  `id` VARCHAR(100) NOT NULL,
  `whatsapp` VARCHAR(50) NULL,
  `google_maps_link` TEXT NULL,
  `image` TEXT NULL,
  `website` TEXT NULL,
  `address` TEXT NULL,
  `city` VARCHAR(100) NULL,
  `main_image` TEXT NULL,
  `latitude` DECIMAL(10,7) NULL,
  `rating` DECIMAL(3,2) NULL,
  `review_count` INT NULL,
  `description` TEXT NULL,
  `price_range` VARCHAR(50) NULL,
  `source` VARCHAR(100) NULL,
  `is_verified` TINYINT(1) NULL,
  `phone` VARCHAR(50) NULL,
  `name` VARCHAR(255) NULL,
  `google_place_id` VARCHAR(255) NULL,
  `category` VARCHAR(100) NULL,
  `last_synced` TEXT NULL,
  `featured_until` TEXT NULL,
  `is_featured` TINYINT(1) NULL,
  `longitude` DECIMAL(10,7) NULL,
  `created_date` DATETIME NULL,
  `updated_date` DATETIME NULL,
  `created_by_id` VARCHAR(100) NULL,
  `created_by` VARCHAR(255) NULL,
  `is_sample` TINYINT(1) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `listing` (`whatsapp`, `google_maps_link`, `image`, `website`, `address`, `city`, `main_image`, `latitude`, `rating`, `review_count`, `description`, `price_range`, `source`, `is_verified`, `phone`, `name`, `google_place_id`, `category`, `last_synced`, `featured_until`, `is_featured`, `longitude`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES (NULL, 'https://www.google.com/maps/search/?api=1&query=Jobo+Restaurant+El+Gouna', NULL, NULL, 'Abu Tig Marina, El Gouna, Red Sea', 'el-gouna', NULL, NULL, 4.7, 510, 'Popular burger and grill restaurant right on the Marina. Best burgers in El Gouna, excellent craft cocktails, and a lively atmosphere that fills up by 8pm. Good for groups. Outdoor marina terrace seating.', 'moderate', 'verified_local', 1, '+20 65 358 0190', 'Jobo Restaurant El Gouna', NULL, 'restaurant', NULL, NULL, 0, NULL, '69ded71d35023d1685e456f1', '2026-04-15 00:09:01', '2026-04-15 00:09:01', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `listing` (`whatsapp`, `google_maps_link`, `image`, `website`, `address`, `city`, `main_image`, `latitude`, `rating`, `review_count`, `description`, `price_range`, `source`, `is_verified`, `phone`, `name`, `google_place_id`, `category`, `last_synced`, `featured_until`, `is_featured`, `longitude`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES (NULL, 'https://www.google.com/maps/search/?api=1&query=Sultan+Bey+Hotel+El+Gouna', NULL, NULL, 'El Gouna Downtown, El Gouna, Red Sea', 'el-gouna', NULL, NULL, 4.4, 670, 'Best-value boutique hotel in El Gouna. Distinctive Egyptian architectural style, rooftop terrace, pool, and breakfast included. Small and personal — far more charming than the large resorts. Walking distance to Kite Beach. Ideal for independent travelers.', 'moderate', 'verified_local', 1, '+20 65 354 9300', 'Sultan Bey Hotel El Gouna', NULL, 'hotel', NULL, NULL, 0, NULL, '69ded71d35023d1685e456f8', '2026-04-15 00:09:01', '2026-04-15 00:09:01', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `listing` (`whatsapp`, `google_maps_link`, `image`, `website`, `address`, `city`, `main_image`, `latitude`, `rating`, `review_count`, `description`, `price_range`, `source`, `is_verified`, `phone`, `name`, `google_place_id`, `category`, `last_synced`, `featured_until`, `is_featured`, `longitude`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES (NULL, 'https://www.google.com/maps/search/?api=1&query=Sheraton+Miramar+El+Gouna', NULL, 'marriott.com', 'Miramar Island, El Gouna, Red Sea', 'el-gouna', NULL, NULL, 4.7, 2100, 'Iconic 5-star resort on its own private island, connected to El Gouna by bridges. Award-winning pyramid design by Michael Graves. Private beach, 4 pools, 5 restaurants. Family-friendly with kids\' club. One of El Gouna\'s most architecturally distinctive hotels.', 'luxury', 'verified_local', 1, '+20 65 354 5845', 'Sheraton Miramar Resort El Gouna', NULL, 'hotel', NULL, NULL, 1, NULL, '69ded71d35023d1685e456fa', '2026-04-15 00:09:01', '2026-04-15 00:09:01', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `listing` (`whatsapp`, `google_maps_link`, `image`, `website`, `address`, `city`, `main_image`, `latitude`, `rating`, `review_count`, `description`, `price_range`, `source`, `is_verified`, `phone`, `name`, `google_place_id`, `category`, `last_synced`, `featured_until`, `is_featured`, `longitude`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES (NULL, 'https://www.google.com/maps/search/?api=1&query=Zaalouk+Restaurant+El+Gouna+Egypt', NULL, NULL, 'Abu Tig Marina, El Gouna, Red Sea', 'el-gouna', NULL, NULL, 4.8, 680, 'One of El Gouna\'s most beloved restaurants at the Abu Tig Marina. Moroccan and Mediterranean cuisine — tagines, couscous, mezze, fresh seafood, and exceptional cocktails. Rooftop terrace with marina views. Always busy — reserve at least a day ahead in high season.', 'moderate', 'verified_local', 1, '+20 65 358 0180', 'Zaalouk Restaurant', NULL, 'restaurant', NULL, NULL, 1, NULL, '69ded71d35023d1685e456f0', '2026-04-15 00:09:01', '2026-04-15 00:09:01', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `listing` (`whatsapp`, `google_maps_link`, `image`, `website`, `address`, `city`, `main_image`, `latitude`, `rating`, `review_count`, `description`, `price_range`, `source`, `is_verified`, `phone`, `name`, `google_place_id`, `category`, `last_synced`, `featured_until`, `is_featured`, `longitude`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES (NULL, 'https://www.google.com/maps/search/?api=1&query=La+Tortuga+El+Gouna+Egypt', NULL, NULL, 'El Gouna Downtown, El Gouna, Red Sea', 'el-gouna', NULL, NULL, 4.9, 420, 'Beloved Italian restaurant run by an Italian family for 15+ years. Wood-fired pizza, fresh pasta, and the best tiramisu on the Red Sea. Tiny — only 10 tables — so reservation is essential. Closed Wednesdays. Considered by many the finest restaurant in El Gouna.', 'moderate', 'verified_local', 1, '+20 65 358 0300', 'La Tortuga Restaurant', NULL, 'restaurant', NULL, NULL, 1, NULL, '69ded71d35023d1685e456ef', '2026-04-15 00:09:01', '2026-04-15 00:09:01', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `listing` (`whatsapp`, `google_maps_link`, `image`, `website`, `address`, `city`, `main_image`, `latitude`, `rating`, `review_count`, `description`, `price_range`, `source`, `is_verified`, `phone`, `name`, `google_place_id`, `category`, `last_synced`, `featured_until`, `is_featured`, `longitude`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES (NULL, 'https://www.google.com/maps/search/?api=1&query=Saffron+El+Gouna', NULL, NULL, 'Abu Tig Marina, El Gouna, Red Sea', 'el-gouna', NULL, NULL, 4.5, 290, 'Best Asian food in El Gouna. Thai curries, sushi, dim sum, and creative cocktails. Waterfront Marina tables available. Popular with the international expat crowd — a refreshing change from Egyptian and Mediterranean menus.', 'premium', 'verified_local', 1, NULL, 'Saffron Asian Fusion', NULL, 'restaurant', NULL, NULL, 0, NULL, '69ded71d35023d1685e456f4', '2026-04-15 00:09:01', '2026-04-15 00:09:01', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
