-- ============================================================
-- Table: live_situation
-- ============================================================

CREATE TABLE IF NOT EXISTS `live_situation` (
  `id` VARCHAR(100) NOT NULL,
  `city` VARCHAR(100) NULL,
  `temperature_c` DECIMAL(5,2) NULL,
  `recommendation` TEXT NULL,
  `meal_range` VARCHAR(100) NULL,
  `coffee_range` VARCHAR(100) NULL,
  `source` VARCHAR(255) NULL,
  `usd_to_egp` DECIMAL(10,4) NULL,
  `prices_summary` TEXT NULL,
  `update_date` DATE NULL,
  `alerts` TEXT NULL,
  `rub_to_egp` DECIMAL(10,4) NULL,
  `eur_to_egp` DECIMAL(10,4) NULL,
  `weather` TEXT NULL,
  `gbp_to_egp` DECIMAL(10,4) NULL,
  `currency_note` TEXT NULL,
  `taxi_range` VARCHAR(100) NULL,
  `events` TEXT NULL,
  `status` VARCHAR(50) NULL,
  `traffic` TEXT NULL,
  `created_date` DATETIME NULL,
  `updated_date` DATETIME NULL,
  `created_by_id` VARCHAR(100) NULL,
  `created_by` VARCHAR(255) NULL,
  `is_sample` TINYINT(1) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `live_situation` (`city`, `temperature_c`, `recommendation`, `meal_range`, `coffee_range`, `source`, `usd_to_egp`, `prices_summary`, `update_date`, `alerts`, `rub_to_egp`, `eur_to_egp`, `weather`, `gbp_to_egp`, `currency_note`, `taxi_range`, `events`, `status`, `traffic`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('aswan', 41.0, 'Plan all outdoor sightseeing for the early morning hours to avoid the intense midday heat and enjoy the sunset from a felucca.', '150-450 EGP', '60-130 EGP', 'AI auto-update (Gemini + web)', 52.9185, 'Prices remain moderate for tourists following currency stabilization, though slightly higher in primary tourist zones.', '2026-05-13', 'Extreme heat warning between 12:00 PM and 4:00 PM; travelers should prioritize hydration and sun protection.', 0.7164, 62.1002, 'Sunny and very hot with clear skies. Typical early summer conditions for Upper Egypt with high UV levels.', 71.6794, 'Rates updated 2026-05-13 from CBE-aligned source. 1 EUR = 62.1002 EGP · 1 USD = 52.9185 EGP', '80-250 EGP', 'Nightly Sound and Light Show at Philae Temple; local nubian cultural performances in Elephantine Island villages.', 'green', 'Generally calm and manageable; river transport via motorboat and felucca remains the most efficient way to reach island attractions.', '69e7c347bffbd487d2dbc3fa', '2026-04-21 18:34:47', '2026-05-13 08:00:39', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `live_situation` (`city`, `temperature_c`, `recommendation`, `meal_range`, `coffee_range`, `source`, `usd_to_egp`, `prices_summary`, `update_date`, `alerts`, `rub_to_egp`, `eur_to_egp`, `weather`, `gbp_to_egp`, `currency_note`, `taxi_range`, `events`, `status`, `traffic`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('luxor', 39.0, 'Visit the Valley of the Kings and Karnak Temple at sunrise to avoid the peak afternoon heat.', '200-500 EGP', '70-130 EGP', 'AI auto-update (Gemini + web)', 52.9185, 'Moderate price increases due to inflation, though favorable for travelers with foreign currency.', '2026-05-13', 'Heat advisory in effect; avoid direct sun exposure between 12:00 PM and 4:00 PM.', 0.7164, 62.1002, 'Clear skies and very hot with a high UV index.', 71.6794, 'Rates updated 2026-05-13 from CBE-aligned source. 1 EUR = 62.1002 EGP · 1 USD = 52.9185 EGP', '80-250 EGP', NULL, 'green', 'Traffic is flowing smoothly with standard activity around the Corniche and ferry docks.', '69e7c347bffbd487d2dbc3f9', '2026-04-21 18:34:47', '2026-05-13 08:00:39', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `live_situation` (`city`, `temperature_c`, `recommendation`, `meal_range`, `coffee_range`, `source`, `usd_to_egp`, `prices_summary`, `update_date`, `alerts`, `rub_to_egp`, `eur_to_egp`, `weather`, `gbp_to_egp`, `currency_note`, `taxi_range`, `events`, `status`, `traffic`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('el-gouna', 29.0, 'Ideal time to visit. Book a sunset dinner at the Marina and take a morning kayak through the lagoons.', '300–900 EGP', '80–160 EGP', 'manual', 52.9185, 'Premium pricing vs Hurghada but affordable for European visitors. Marina restaurants cost 20–40% more than Downtown.', '2026-05-13', NULL, 0.7164, 62.1002, 'Sunny and clear with a gentle lagoon breeze — perfect beach weather.', 71.6794, 'Rates updated 2026-05-13 from CBE-aligned source. 1 EUR = 62.1002 EGP · 1 USD = 52.9185 EGP', '50–100 EGP (tuk-tuk)', 'Kite season in full swing at Mangroovy Beach. Marina restaurants hosting spring dining events.', 'green', 'Tuk-tuks and shuttle boats running smoothly. Marina area and Downtown accessible.', '69e375947197f33c39915727', '2026-04-18 12:14:12', '2026-05-13 08:00:39', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `live_situation` (`city`, `temperature_c`, `recommendation`, `meal_range`, `coffee_range`, `source`, `usd_to_egp`, `prices_summary`, `update_date`, `alerts`, `rub_to_egp`, `eur_to_egp`, `weather`, `gbp_to_egp`, `currency_note`, `taxi_range`, `events`, `status`, `traffic`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('hurghada', 31.0, 'Perfect conditions for scuba diving and boat trips to Giftun Island given the high visibility and calm seas.', '180-600 EGP', '65-140 EGP', 'AI auto-update (Gemini + web)', 52.9185, 'Stable for tourism sectors, offering high value for foreign currency holders despite local inflation.', '2026-05-13', NULL, 0.7164, 62.1002, 'Sunny and clear skies with low humidity and pleasant sea breezes.', 71.6794, 'Rates updated 2026-05-13 from CBE-aligned source. 1 EUR = 62.1002 EGP · 1 USD = 52.9185 EGP', '85-300 EGP', 'Red Sea Watersports Festival and weekly live performances at the Hurghada Marina.', 'green', 'Flowing smoothly; light congestion typically limited to Sheraton Road during evening hours.', '69d7d52c12e4eaaa47d2e640', '2026-04-09 16:34:52', '2026-05-13 08:00:40', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `live_situation` (`city`, `temperature_c`, `recommendation`, `meal_range`, `coffee_range`, `source`, `usd_to_egp`, `prices_summary`, `update_date`, `alerts`, `rub_to_egp`, `eur_to_egp`, `weather`, `gbp_to_egp`, `currency_note`, `taxi_range`, `events`, `status`, `traffic`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('sharm-el-sheikh', 33.0, 'Perfect conditions for snorkeling and diving in the Ras Mohammed National Park before the extreme summer heat begins.', '450-1200 EGP', '100-220 EGP', 'AI auto-update (Gemini + web)', 52.9185, 'Moderate for international travelers due to favorable exchange rates, though local inflation is elevated.', '2026-05-13', 'Standard security measures in place; travelers are advised to remain within the South Sinai security perimeter.', 0.7164, 62.1002, 'Sunny and clear with low humidity; ideal for water activities.', 71.6794, 'Rates updated 2026-05-13 from CBE-aligned source. 1 EUR = 62.1002 EGP · 1 USD = 52.9185 EGP', '200-550 EGP', 'Red Sea Scuba Festival and various beach resort seasonal concerts.', 'green', 'Light traffic within the resort areas; tourist shuttles and taxis operating normally.', '69d7d52c12e4eaaa47d2e641', '2026-04-09 16:34:52', '2026-05-13 08:00:40', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `live_situation` (`city`, `temperature_c`, `recommendation`, `meal_range`, `coffee_range`, `source`, `usd_to_egp`, `prices_summary`, `update_date`, `alerts`, `rub_to_egp`, `eur_to_egp`, `weather`, `gbp_to_egp`, `currency_note`, `taxi_range`, `events`, `status`, `traffic`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('global', NULL, NULL, NULL, NULL, 'seed-data', 52.9185, NULL, '2026-05-13', NULL, 0.7164, 62.1002, NULL, 71.6794, 'Rates updated 2026-05-13 from CBE-aligned source. 1 EUR = 62.1002 EGP · 1 USD = 52.9185 EGP', NULL, NULL, 'green', NULL, '69cdb50a3e678fa9b5df4e78', '2026-04-02 00:15:06', '2026-05-13 08:00:40', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `live_situation` (`city`, `temperature_c`, `recommendation`, `meal_range`, `coffee_range`, `source`, `usd_to_egp`, `prices_summary`, `update_date`, `alerts`, `rub_to_egp`, `eur_to_egp`, `weather`, `gbp_to_egp`, `currency_note`, `taxi_range`, `events`, `status`, `traffic`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('hurghada', 26.0, 'Great beach and diving day. Use Careem for airport transfer. Buy SIM at official Vodafone kiosk only.', '100–300', '40–90', 'seed-data', 52.9185, NULL, '2026-05-13', 'None', 0.7164, 62.1002, '26°C, sunny, light sea breeze', 71.6794, 'Rates updated 2026-05-13 from CBE-aligned source. 1 EUR = 62.1002 EGP · 1 USD = 52.9185 EGP', '30–80', 'None reported', 'green', 'Normal — airport and roads clear', '69cdb50a3e678fa9b5df4e79', '2026-04-02 00:15:06', '2026-05-13 08:00:40', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `live_situation` (`city`, `temperature_c`, `recommendation`, `meal_range`, `coffee_range`, `source`, `usd_to_egp`, `prices_summary`, `update_date`, `alerts`, `rub_to_egp`, `eur_to_egp`, `weather`, `gbp_to_egp`, `currency_note`, `taxi_range`, `events`, `status`, `traffic`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('sharm-el-sheikh', 27.0, 'Perfect diving conditions. Buy SIM at official Vodafone kiosk only. Old Market — agree prices before buying.', '120–350', '50–100', 'seed-data', 52.9185, NULL, '2026-05-13', 'None', 0.7164, 62.1002, '27°C, clear, Red Sea breeze', 71.6794, 'Rates updated 2026-05-13 from CBE-aligned source. 1 EUR = 62.1002 EGP · 1 USD = 52.9185 EGP', '40–100', 'None reported', 'green', 'Normal operations', '69cdb50a3e678fa9b5df4e7a', '2026-04-02 00:15:06', '2026-05-13 08:00:46', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);

