INSERT INTO `nightlife_venue` (`safety_rating`, `city`, `phone`, `dress_code`, `main_image`, `name`, `description`, `price_range`, `location`, `entry_fee`, `type`, `is_verified`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('safe', 'hurghada', NULL, NULL, 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/133c84867_MangoBar.jpg', 'Mango Bar', 'El Gouna\'s most iconic bar on the Abu Tig Marina waterfront. Open until 3am with DJ nights Thursday to Saturday. The social hub of El Gouna for expats and long-stay tourists. Excellent cocktails, cold Stella beer, and marina views. Smartly casual after 9pm.', 'moderate', 'Abu Tig Marina, El Gouna', NULL, 'bar', 1, '69ded71d35023d1685e456e9', '2026-04-15 00:09:01', '2026-04-16 01:34:45', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `nightlife_venue` (`safety_rating`, `city`, `phone`, `dress_code`, `main_image`, `name`, `description`, `price_range`, `location`, `entry_fee`, `type`, `is_verified`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('safe', 'hurghada', NULL, NULL, 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/017e253bb_OrcaBeachClub.jpg', 'Orca Beach Club', 'Full-day beach club with pool, sun loungers, bar and restaurant. Famous for its DJ nights, fire shows, and themed party events in high season. Most popular beach party venue in El Gouna. Entry fee includes drink credit. Book ahead for special event nights.', 'premium', 'El Gouna Beach, El Gouna', 300.0, 'beach_club', 1, '69ded71d35023d1685e456ea', '2026-04-15 00:09:01', '2026-04-16 01:38:27', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `nightlife_venue` (`safety_rating`, `city`, `phone`, `dress_code`, `main_image`, `name`, `description`, `price_range`, `location`, `entry_fee`, `type`, `is_verified`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('safe', 'hurghada', NULL, NULL, 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/e7eedfd50_LaLunaRooftopBar.jfif', 'La Luna Rooftop Bar', 'Elevated rooftop bar in El Gouna Downtown with 360° views of the lagoons and islands. Perfect for sunset cocktails and wine. Intimate romantic atmosphere. Arrives at its best 5–7pm when the lagoons glow golden. Popular with couples.', 'moderate', 'El Gouna Downtown, El Gouna', NULL, 'rooftop', 1, '69ded71d35023d1685e456ec', '2026-04-15 00:09:01', '2026-04-16 01:42:53', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `nightlife_venue` (`safety_rating`, `city`, `phone`, `dress_code`, `main_image`, `name`, `description`, `price_range`, `location`, `entry_fee`, `type`, `is_verified`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('safe', 'hurghada', NULL, NULL, 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/01353078d_KiteBarElGouna.jfif', 'Kite Bar El Gouna', 'Legendary open-air bar at Kite Beach with front-row views of world-class kitesurfing. Fresh grills, cold beer, and sunsets that justify the trip alone. Very popular with the kite crowd and sports crowd. Open from 10am. Book for weekend sunsets in high season.', 'moderate', 'Mangroovy/Kite Beach, El Gouna', NULL, 'beach_club', 1, '69ded71d35023d1685e456ee', '2026-04-15 00:09:01', '2026-04-16 02:03:08', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `nightlife_venue` (`safety_rating`, `city`, `phone`, `dress_code`, `main_image`, `name`, `description`, `price_range`, `location`, `entry_fee`, `type`, `is_verified`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('safe', 'hurghada', NULL, NULL, 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/fb1651f2c_HemingwayBarr.jfif', 'Hemingway Bar', 'Long-running El Gouna institution with classic bar atmosphere. Exceptional whiskey and spirits selection. Quiet enough for conversation — a welcome break from DJ noise. Popular with European long-stays and the sailing crowd. Opens at 5pm daily.', 'moderate', 'El Gouna Downtown, El Gouna', NULL, 'bar', 1, '69ded71d35023d1685e456eb', '2026-04-15 00:09:01', '2026-04-16 01:41:10', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `nightlife_venue` (`safety_rating`, `city`, `phone`, `dress_code`, `main_image`, `name`, `description`, `price_range`, `location`, `entry_fee`, `type`, `is_verified`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('safe', 'hurghada', '+2012 81992000', NULL, 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/7e3093f49_th.jfif', 'Tamr Henna Beach Bar', 'Low-key beachfront bar at El Gouna\'s main public beach. Relaxed daytime and early evening crowd. Cold drinks, shisha, light snacks. More laid-back than Orca — ideal for afternoon unwinding rather than late-night parties. Cash only.', 'budget', 'El Gouna Main Beach, El Gouna', NULL, 'bar', 0, '69ded71d35023d1685e456ed', '2026-04-15 00:09:01', '2026-04-16 01:45:31', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `nightlife_venue` (`safety_rating`, `city`, `phone`, `dress_code`, `main_image`, `name`, `description`, `price_range`, `location`, `entry_fee`, `type`, `is_verified`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('safe', 'hurghada', '+20 65 345 0888', 'Beach/casual', 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/ad90b000e_BeachAlbatrosAquaParkClub.jpg', 'Beach Albatros Aqua Park Club', 'By day a waterpark, by night transforms into a beach party venue. Full moon parties every month. Live entertainment, fire shows, laser shows. All-inclusive day + night packages available.', 'moderate', 'Sahl Hasheesh Road, Hurghada', 150.0, 'beach_club', 1, '69d7d4db12e4eaaa47d2e61b', '2026-04-09 16:33:31', '2026-04-16 02:13:30', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `nightlife_venue` (`safety_rating`, `city`, `phone`, `dress_code`, `main_image`, `name`, `description`, `price_range`, `location`, `entry_fee`, `type`, `is_verified`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('safe', 'hurghada', NULL, 'Very casual', 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/cecaf65fa_BobMarleyBarHurghada.jpg', 'Bob Marley Bar — Hurghada', 'Reggae-themed bar on the Hurghada Marina. Relaxed vibes, cold beer, reggae and pop music. Very popular with Russians and Eastern Europeans. Often has live guitar music on weekends. No entry fee.', 'moderate', 'Hurghada Marina (El Mamsha)', 0.0, 'bar', 0, '69d7d4db12e4eaaa47d2e620', '2026-04-09 16:33:31', '2026-04-16 02:20:01', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
