INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Dinner at Marina restaurant (per person)', 'El Gouna Marina restaurants are pricier than Hurghada. Always check menu prices before sitting. Some menus are priced in EUR — ask for EGP price list. Avoid restaurants with touts standing outside.', 'hurghada', NULL, 700, 'food', 500, 1500, '69ded74535023d1685e45705', '2026-04-15 00:09:41', '2026-04-22 18:34:30', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Airport transfer (Hurghada Airport to El Gouna)', 'Only 30km and 30 minutes. Pre-book through hotel or official transfer desk inside arrivals hall. Avoid men approaching you outside — they charge 2-3x. Shared taxi: 150-200 EGP/person.', 'hurghada', NULL, 1000, 'transport', 500, 1500, '69ded74535023d1685e45707', '2026-04-15 00:09:41', '2026-04-22 18:19:51', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Snorkeling day trip to Giftun Island (all-inclusive)', 'Price should include boat, equipment, guide, and lunch. Book direct at the marina — hotel excursion desks add 30-50% commission. Morning departures (9am) have calmer seas.', 'hurghada', NULL, 2000, 'activities', 1500, 3500, '69ded74535023d1685e45708', '2026-04-15 00:09:41', '2026-04-22 18:53:12', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Tuk-tuk ride (any trip within El Gouna)', 'El Gouna\'s main transport. Downtown to Marina is ~80-120 EGP. Always agree price before boarding. 30 EGP is local rate for short hops, tourists pay 80-150 EGP.', 'hurghada', NULL, 120, 'transport', 80, 250, '69ded74535023d1685e45702', '2026-04-15 00:09:41', '2026-04-22 18:55:27', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Beach club day pass (Zeytuna/Mangroovy)', 'El Gouna\'s best beaches are attached to hotels or clubs. Non-guests can buy day passes. Zeytuna Beach: ~500-700 EGP. Mangroovy: ~200-300 EGP entry. Includes sunbed.', 'hurghada', NULL, 750, 'accommodation', 500, 1000, '69ded74535023d1685e45709', '2026-04-15 00:09:41', '2026-04-22 18:21:14', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Scuba diving (2 dives with full equipment)', 'PADI 5-star centers at Abu Tig Marina. Includes boat, guide, tanks, wetsuit. Nitrox extra. Best sites: Shaab Sharm, El Fanous reef. Book direct at marina — avoid hotel booking desks (add 40% markup).', 'hurghada', NULL, 4200, 'activities', 2800, 6000, '69ded74535023d1685e45704', '2026-04-15 00:09:41', '2026-04-22 18:49:29', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Kitesurfing lesson (2-3 hours, IKO certified)', 'El Gouna is world-famous for kite. IKO-certified schools: Kite House, Freeride El Gouna. Never book with uncertified operators. Ask to see instructor IKO card.', 'hurghada', NULL, 3500, 'activities', 2500, 5500, '69ded74535023d1685e45703', '2026-04-15 00:09:41', '2026-04-22 18:42:55', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Golf round (18 holes, cart included)', 'El Gouna Golf Club is one of the best in the Middle East. Rates are higher Dec-Apr (peak season). Twilight rates after 3pm are cheaper. Equipment rental available.', 'hurghada', NULL, 5500, 'activities', 4000, 7000, '69ded74535023d1685e4570a', '2026-04-15 00:09:41', '2026-04-22 18:39:03', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Bicycle rental (full day)', 'Best way to explore El Gouna independently. Hotel rentals are most expensive. Downtown rental shops are cheapest. Check brakes and tires before renting.', 'hurghada', NULL, 600, 'transport', 400, 1000, '69ded74535023d1685e45706', '2026-04-15 00:09:41', '2026-04-22 18:22:08', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Cocktail at Marina bar', 'El Gouna Marina bars are pricier than downtown. Mango Bar and La Luna are best value for quality. Avoid hotel rooftop bars which charge European prices.', 'hurghada', NULL, 200, 'food', 150, 450, '69ded74535023d1685e4570b', '2026-04-15 00:09:41', '2026-04-22 18:27:17', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Papyrus painting (tourist souvenir)', 'Most \'papyrus\' is banana leaf paper. Real papyrus from papyrus institute costs 600-2000 EGP and is worth it.', 'hurghada', NULL, 600, 'shopping', 200, 1500, '69d7d46712e4eaaa47d2e5bd', '2026-04-09 16:31:35', '2026-04-22 18:47:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Bottled water (1.5 liter, supermarket)', 'Buy Baraka or Siwa from supermarkets, not from hotel minibars (3-4x markup).', 'hurghada', NULL, 10, 'food', 10, 40, '69d7d46712e4eaaa47d2e5be', '2026-04-09 16:31:35', '2026-04-09 16:31:35', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('3-star hotel (per night, walk-in rate)', 'Online booking is almost always cheaper. Check Booking.com before accepting a walk-in rate.', 'hurghada', NULL, 2500, 'accommodation', 1500, 4000, '69d7d46712e4eaaa47d2e5ba', '2026-04-09 16:31:35', '2026-04-22 18:12:46', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Exchange rate USD to EGP (bank/ATM)', '100 USD = 5292 EGP at CBE rate 2026-05-13. Any offer below 4763 EGP per 100 USD is a scam. Source: cbe.org.eg', 'all', NULL, 5292, 'other', 5292, 4498, '69d7d46712e4eaaa47d2e5bc', '2026-04-09 16:31:35', '2026-05-13 06:00:55', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Vodafone tourist SIM (15GB data + calls)', 'Only buy from official Vodafone stores. Street sellers often sell fake or expired SIMs.', 'hurghada', NULL, 150, 'telecom', 150, 400, '69d7d46712e4eaaa47d2e5bb', '2026-04-09 16:31:35', '2026-04-09 16:31:35', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Coffee (Nescafe or Turkish) at cafe', 'Starbucks-style cafes in malls charge 80-120 EGP. Local cafes serve equally good coffee for 50-80 EGP.', 'hurghada', NULL, 80, 'food', 50, 120, '69d7d46712e4eaaa47d2e5b3', '2026-04-09 16:31:35', '2026-04-22 18:29:43', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
