INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Shisha (hookah) at a cafe', 'Ask price before ordering. Some tourist cafes charge 5x local price. Always confirm in advance.', 'hurghada', NULL, 150, 'food', 80, 250, '69d7d46712e4eaaa47d2e5b2', '2026-04-09 16:31:35', '2026-04-22 18:50:02', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
