INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Hotel breakfast (3-star hotel)', 'Most 3-star hotels include breakfast. If not included, local cafes near Dahar are much cheaper.', 'hurghada', NULL, 150, 'food', 0, 0, '69d7d46712e4eaaa47d2e5b4', '2026-04-09 16:31:35', '2026-04-09 16:31:35', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
