INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Dinner at Naama Bay restaurant (main course)', 'Always check menu prices before ordering. Some tourist restaurants don\'t display prices.', 'sharm-el-sheikh', NULL, 400, 'food', 250, 600, '69d7d46712e4eaaa47d2e5a3', '2026-04-09 16:31:35', '2026-04-22 19:10:19', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Diving day trip (2 dives, Ras Mohammed)', 'Camel Dive Club and Emperor Divers are the most reputable. Don\'t compromise on safety for price.', 'sharm-el-sheikh', NULL, 2600, 'activities', 1500, 3000, '69d7d46712e4eaaa47d2e5a4', '2026-04-09 16:31:35', '2026-04-22 19:16:12', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Camel ride (30 minutes on beach)', 'Agree price AND duration BEFORE mounting. Some handlers demand 200 USD after a \'5-minute ride\'.', 'sharm-el-sheikh', NULL, 250, 'activities', 150, 500, '69d7d46712e4eaaa47d2e5a7', '2026-04-09 16:31:35', '2026-04-22 19:09:32', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Naama Bay boat trip snorkeling (4 hours)', 'Don\'t book through your hotel. Walk to the marina and negotiate directly with boat operators.', 'sharm-el-sheikh', NULL, 700, 'activities', 500, 1500, '69d7d46712e4eaaa47d2e5a9', '2026-04-09 16:31:35', '2026-04-22 19:18:52', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Thistlegorm wreck diving (8-hour trip)', 'Full-day boat trip including 2 dives, lunch, equipment. Only advanced certified divers.', 'sharm-el-sheikh', NULL, 6500, 'activities', 4000, 9000, '69d7d46712e4eaaa47d2e5a5', '2026-04-09 16:31:35', '2026-04-22 19:23:02', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Seafood dinner in Naama Bay (per person)', 'Dananeer, Fares Seafood are reliable. Fish charged by weight — always confirm price per kilo before ordering. Fares Seafood offers best value in Naama Bay.', 'sharm-el-sheikh', NULL, 700, 'food', 350, 1200, '69d6bde26d4db8dc94ed9df2', '2026-04-08 20:43:14', '2026-04-22 19:19:33', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Budget meal at local restaurant (Egyptian)', 'Kofta, rice, salad, bread and soft drink. El Halaka Fish, Boska, and Nubian Egyptian Café offer best value. Never accept menu without prices listed.', 'hurghada', NULL, 250, 'food', 200, 350, '69d6bde26d4db8dc94ed9def', '2026-04-08 20:43:14', '2026-04-22 18:25:53', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('White Island & Ras Mohamed Cruise — Full Day (Sharm)', '7 hours. Lunch + snorkeling gear included. National Park entry fee (~EGP 150) sometimes extra. One of Sharm’s best-value tours.', 'sharm-el-sheikh', NULL, 2200, 'activities', 1500, 3000, '69d6bde26d4db8dc94ed9deb', '2026-04-08 20:43:14', '2026-04-22 19:23:53', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('ATV + Camel + Bedouin BBQ Dinner (Sharm) — 5 hours', 'BESTSELLER with 4.9/5 from 4,283 reviews. Evening timing recommended for sunset views. Book 1 day in advance. Includes hotel pickup.', 'sharm-el-sheikh', NULL, 1500, 'activities', 900, 2500, '69d6bde26d4db8dc94ed9dec', '2026-04-08 20:43:14', '2026-04-22 19:05:20', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Airport taxi (Sharm El Sheikh Airport → Naama Bay)', 'Only 8–10 km from airport. Use the official yellow taxis or pre-book hotel transfer. Agree price before entering. Careem available in Sharm.', 'sharm-el-sheikh', NULL, 350, 'transport', 200, 600, '69d6bde26d4db8dc94ed9df4', '2026-04-08 20:43:14', '2026-04-22 19:06:59', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Mid-range seafood restaurant dinner (per person)', 'Includes fresh fish + sides + soft drink. Starfish and Granada are reliable. Ask price of fish per kilo before ordering — fish is always charged by weight.', 'hurghada', NULL, 500, 'food', 300, 900, '69d6bde26d4db8dc94ed9df0', '2026-04-08 20:43:14', '2026-04-22 18:45:47', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Budget meal at local restaurant (Sharm)', 'Old Market area is cheapest. Naama Bay restaurants are 30–50% more expensive than Old Market for same food quality. Always ask for menu with prices.', 'sharm-el-sheikh', NULL, 400, 'food', 200, 600, '69d6bde26d4db8dc94ed9df1', '2026-04-08 20:43:14', '2026-04-22 19:08:46', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Airport taxi (Hurghada Airport → City Center)', 'Fixed-rate taxis from official airport taxi stand. Agree price BEFORE getting in. Use Careem or Uber app where available — avoids negotiation entirely.', 'hurghada', NULL, 500, 'transport', 350, 1000, '69d6bde26d4db8dc94ed9df3', '2026-04-08 20:43:14', '2026-04-22 18:16:43', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('SIM card — Vodafone 15GB tourist package', 'Buy at official Vodafone/Orange stores, not airport kiosks (double price). Bring passport for registration. Orange and Etisalat also offer similar packages. Best coverage: Vodafone for Hurghada/Sharm, Orange for Luxor/Aswan.', 'all', NULL, 200, 'telecom', 180, 400, '69d6bde26d4db8dc94ed9df5', '2026-04-08 20:43:14', '2026-04-08 20:43:14', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Quad Biking Desert Safari — 3 hours', 'Double-rider quad is better value for couples. Price includes guide, tea at Bedouin tent, hotel transfer. Avoid booking through hotel — direct with tour operator is cheaper.', 'hurghada', NULL, 1400, 'activities', 800, 2500, '69d6bde26d4db8dc94ed9de8', '2026-04-08 20:43:14', '2026-04-22 18:48:06', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Luxor Day Trip from Hurghada — By Bus (group, guide + entries included)', '~4:30 AM departure, return ~10 PM. Long day but extraordinary. Includes Egyptologist guide, all entry fees, lunch. Private transfer by plane: EGP 11,300–16,500.', 'hurghada', NULL, 4500, 'activities', 3000, 7500, '69d6bde26d4db8dc94ed9dea', '2026-04-08 20:43:14', '2026-04-22 18:44:10', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Dolphin House Snorkeling Cruise — Full Day', 'Wild dolphins not guaranteed but very likely. Full day, lunch included. Avoid tours that say ‘guaranteed dolphins’ — that’s a red flag.', 'hurghada', NULL, 2200, 'activities', 1200, 4000, '69d6bde26d4db8dc94ed9de7', '2026-04-08 20:43:14', '2026-04-22 18:36:01', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Orange Bay Island Snorkeling — Full Day (group, lunch included)', 'Always includes hotel transfer, lunch, snorkeling gear. EGP 150 National Park fee payable on day. Compare 3 operators before booking.', 'hurghada', NULL, 1800, 'activities', 1200, 3500, '69d6bde26d4db8dc94ed9de6', '2026-04-08 20:43:14', '2026-04-22 18:46:36', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Intro Scuba Diving — 1 dive, equipment included', 'No license needed. Certified instructor. Always check dive center safety record. Look for SSI or PADI certified centers.', 'hurghada', NULL, 2500, 'activities', 1600, 4500, '69d6bde26d4db8dc94ed9de9', '2026-04-08 20:43:14', '2026-04-22 18:42:17', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Airport Taxi to Hotel', 'Agree on price BEFORE getting in. Use Uber/Careem for fixed pricing.', 'sharm-el-sheikh', NULL, 500, 'transport', 350, 800, '69c68be623533aadb23e18b6', '2026-03-27 13:53:42', '2026-04-22 19:06:06', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Airport Taxi to Hotel', 'Official airport transfer booths are safest.', 'hurghada', NULL, 500, 'transport', 300, 1000, '69c68be623533aadb23e18b7', '2026-03-27 13:53:42', '2026-04-22 18:14:30', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('1L Bottled Water', 'Buy from shops, not street vendors near tourist sites.', 'all', NULL, 10, 'food', 5, 30, '69c68be623533aadb23e18b8', '2026-03-27 13:53:42', '2026-03-27 13:53:42', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Local SIM Card (Vodafone)', 'Buy from official Vodafone/Orange stores only.', 'all', NULL, 200, 'telecom', 150, 500, '69c68be623533aadb23e18b9', '2026-03-27 13:53:42', '2026-03-27 13:53:42', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Diving Session (2 dives)', 'Book with PADI-certified centers. Check equipment quality.', 'sharm-el-sheikh', NULL, 2500, 'activities', 1500, 3000, '69c68be623533aadb23e18ba', '2026-03-27 13:53:42', '2026-04-22 19:15:21', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_guide` (`item`, `notes`, `city`, `main_image`, `fair_tourist_price`, `category`, `local_price`, `scam_price`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Restaurant Meal (mid-range)', 'Check the menu for prices before ordering. Avoid places without visible menus.', 'all', NULL, 200, 'food', 100, 500, '69c68be623533aadb23e18bb', '2026-03-27 13:53:42', '2026-03-27 13:53:42', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
