-- ============================================================
-- Table: price_insight
-- ============================================================

CREATE TABLE IF NOT EXISTS `price_insight` (
  `id` VARCHAR(100) NOT NULL,
  `context_note` TEXT NULL,
  `is_active` TINYINT(1) NULL,
  `report_count` INT NULL,
  `city` VARCHAR(100) NULL,
  `service_name` VARCHAR(255) NULL,
  `local_price_max` INT NULL,
  `location_label` VARCHAR(255) NULL,
  `reported_tourist_price` INT NULL,
  `local_price_min` INT NULL,
  `category` VARCHAR(100) NULL,
  `trust_label` VARCHAR(50) NULL,
  `created_date` DATETIME NULL,
  `updated_date` DATETIME NULL,
  `created_by_id` VARCHAR(100) NULL,
  `created_by` VARCHAR(255) NULL,
  `is_sample` TINYINT(1) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `price_insight` (`context_note`, `is_active`, `report_count`, `city`, `service_name`, `local_price_max`, `location_label`, `reported_tourist_price`, `local_price_min`, `category`, `trust_label`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Shared by traveler from USA. Cumin, coriander, turmeric blends. First price quoted is always 3–4x the fair rate — negotiate confidently.', 1, 3, 'cairo', 'Spices bag (Khan El Khalili)', 200, 'Khan El Khalili market, Cairo', 550, 100, 'shopping', 'community', '69e698d0b3c2316ba418fc25', '2026-04-20 21:21:20', '2026-04-20 21:26:33', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_insight` (`context_note`, `is_active`, `report_count`, `city`, `service_name`, `local_price_max`, `location_label`, `reported_tourist_price`, `local_price_min`, `category`, `trust_label`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Shared by traveler from UK. Hotel transfer desks often overcharge — negotiate directly.', 1, 2, 'sharm-el-sheikh', 'Airport → Naama Bay taxi', 300, 'Sharm El Sheikh Airport', 525, 200, 'taxi', 'community', '69e698d0b3c2316ba418fc1b', '2026-04-20 21:21:20', '2026-04-20 21:26:32', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_insight` (`context_note`, `is_active`, `report_count`, `city`, `service_name`, `local_price_max`, `location_label`, `reported_tourist_price`, `local_price_min`, `category`, `trust_label`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Shared by traveler from Netherlands. Marina restaurants charge 2–3x more than local spots inland.', 1, 4, 'hurghada', 'Local restaurant meal', 400, 'Hurghada city area', 750, 200, 'food_drinks', 'community', '69e698d0b3c2316ba418fc1e', '2026-04-20 21:21:20', '2026-04-20 21:26:32', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_insight` (`context_note`, `is_active`, `report_count`, `city`, `service_name`, `local_price_max`, `location_label`, `reported_tourist_price`, `local_price_min`, `category`, `trust_label`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Shared by traveler from USA. Tourist-facing cafes on the promenade charge significantly more.', 1, 2, 'sharm-el-sheikh', 'Coffee at café', 200, 'Naama Bay, Sharm El Sheikh', 375, 120, 'food_drinks', 'community', '69e698d0b3c2316ba418fc20', '2026-04-20 21:21:20', '2026-04-20 21:26:32', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_insight` (`context_note`, `is_active`, `report_count`, `city`, `service_name`, `local_price_max`, `location_label`, `reported_tourist_price`, `local_price_min`, `category`, `trust_label`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Shared by traveler from Germany. Agree on price before getting in — metered taxis are rare.', 1, 3, 'hurghada', 'Airport → City Center taxi', 350, 'Hurghada Airport', 600, 250, 'taxi', 'community', '69e698d0b3c2316ba418fc1a', '2026-04-20 21:21:20', '2026-04-20 21:26:31', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `price_insight` (`context_note`, `is_active`, `report_count`, `city`, `service_name`, `local_price_max`, `location_label`, `reported_tourist_price`, `local_price_min`, `category`, `trust_label`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('Shared by traveler from Poland. Includes equipment and guide. Book directly at the marina rather than through hotel desks.', 1, 5, 'hurghada', 'Snorkeling day trip', 3000, 'Hurghada Marina (boat departure)', 5000, 2000, 'activities', 'community', '69e698d0b3c2316ba418fc21', '2026-04-20 21:21:20', '2026-04-20 21:26:33', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);

-- ============================================================
-- Table: remote_work_spot
