CREATE TABLE IF NOT EXISTS `remote_work_spot` (
  `id` VARCHAR(100) NOT NULL,
  `wifi_reliability` VARCHAR(50) NULL,
  `ac` TINYINT(1) NULL,
  `city` VARCHAR(100) NULL,
  `price_per_hour` INT NULL,
  `wifi_speed_mbps` INT NULL,
  `description` TEXT NULL,
