INSERT INTO `saved_itinerary` (`user_email`, `city`, `days`, `interests`, `city_label`, `travelers`, `itinerary_text`, `budget`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('memoelpop026@gmail.com', 'cairo', 7, 'Diving & Snorkeling, History & Temples, Beach & Relaxation, Nightlife, Local Culture', 'Cairo + Pyramids', 2, '**7-Day Egypt Travel Itinerary for Cairo + Pyramids**

**Day 1 — [Arrival & Local Culture]**  
- Morning: Arrive in Cairo, transfer to hotel (Mid-range hotel: €50 per night) = 2,700 EGP  
- Afternoon: Visit the Egyptian Museum (Tickets: 200 EGP per person) = 400 EGP  
- Evening: Dinner at a local restaurant (Avg. meal: 200 EGP per person) = 400 EGP  
- 💡 Tip: Use Uber for convenient transportation around the city.

**Day 2 — [History & Temples]**  
- Morning: Visit the Pyramids of Giza (Entry: 200 EGP per person, Camel ride: 300 EGP) = 1,000 EGP  
- Afternoon: Explore the Sphinx + nearby temples (amount included with Pyramids entry)  
- Evening: Attend a Sound & Light Show at the Pyramids (Tickets: 300 EGP per person) = 600 EGP  
- 💡 Tip: Go early to avoid crowds at the Pyramids.

**Day 3 — [Beach & Relaxation]**  
- Morning: Day trip to Ain Sokhna Beach (Transport: 800 EGP round trip for two) = 800 EGP  
- Afternoon: Enjoy the beach (Entrance fee: 250 EGP for two) = 250 EGP  
- Evening: Dinner at a beachside restaurant (Avg. meal: 200 EGP per person) = 400 EGP  
- 💡 Tip: Bring your own snacks and drinks for the day at the beach to save money.

**Day 4 — [Diving & Snorkeling]**  
- Morning: Depart for Sharm El Sheikh (Bus: 2,000 EGP round trip for two) = 2,000 EGP  
- Afternoon: Half-day snorkeling trip (Tour cost: 1,200 EGP for two) = 1,200 EGP  
- Evening: Enjoy a seafood dinner (Avg. meal: 250 EGP per person) = 500 EGP  
- 💡 Tip: Use a reputable local tour operator for snorkeling to ensure safety.

**Day 5 — [Local Culture]**  
- Morning: Explore Khan El Khalili Market (No entry fee)  
- Afternoon: Lunch at a local café (Avg. meal: 150 EGP per person) = 300 EGP  
- Evening: Traditional Egyptian dinner with a cultural performance (Meal & Performance: 700 EGP per person) = 1,400 EGP  
- 💡 Tip: Bargain in the market for the best prices and souvenirs.

**Day 6 — [Nightlife]**  
- Morning: Visit Al-Azhar Park (Entry: 30 EGP per person) = 60 EGP  
- Afternoon: Enjoy a leisurely lunch at the park\'s restaurant (Avg. meal: 200 EGP per person) = 400 EGP  
- Evening: Experience Cairo\'s nightlife in Zamalek (Bar/Club entry: 100 EGP per person) + drinks (800 EGP for two) = 1,000 EGP  
- 💡 Tip: Check club schedules ahead and opt for places with live music.

**Day 7 — [Final Relaxation & Departure]**  
- Morning: Relax at your hotel or visit a local spa (Massage: 600 EGP for two)  
- Afternoon: Last-minute shopping or sightseeing (Transportation: 300 EGP round trip) = 300 EGP  
- Evening: Dinner at your hotel/nearby restaurant (Avg. meal: 200 EGP per person) = 400 EGP  
- 💡 Tip: Confirm airport transfer times the night before for a stress-free departure.

**💰 Budget Summary**  
- Accommodation (7 nights): 2,700 EGP  
- Food: 4,050 EGP  
- Activities: 9,300 EGP  
**Total: 16,050 EGP** (about €297 per person)

**🚫 Top 3 Scams to Avoid**  
1. Extra charges from taxi drivers who don\'t use the meter or overcharge.
2. Street performers or guides who ask for money after a “free” performance or tour.
3. Misleading pricing in tourist shops; always negotiate.

Enjoy your trip to Egypt!', 'Mid-range', '69e0491ce8b5d0ce29c6389c', '2026-04-16 02:27:40', '2026-04-16 02:27:40', '69de7e508ddcff66265e4677', 'memoelpop026@gmail.com', 0);
INSERT INTO `saved_itinerary` (`user_email`, `city`, `days`, `interests`, `city_label`, `travelers`, `itinerary_text`, `budget`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('moa855914@gmail.com', 'hurghada', 3, 'Diving & Snorkeling, History & Temples, Beach & Relaxation, Nightlife', 'Hurghada', 3, '**Hurghada — 3-Day Itinerary (Budget Budget)**
*Best for: Diving & Snorkeling, History & Temples, Beach & Relaxation, Nightlife*

---

**Day 1 — Arrival, Beach & Red Sea First Dip**

- **Morning:** Check into a budget guesthouse in the El Dahar (old town) district — options like **Triton Empire Beach Resort** or small guesthouses along Sharm El Naga road run around **800–1,200 EGP/night for a double room** (shared between your group = ~270–400 EGP/person). After settling in, grab breakfast at a local **ful & ta\'meya spot on El Nasr Street** — a full breakfast with eggs, bread, cheese, and tea costs around **40–60 EGP per person**. Walk to the **free public beach near El Dahar corniche** for a morning swim — no entrance fee.

- **Afternoon:** Head to **Mahmya Island or Sharm El Naga Beach** (closer and cheaper than Mahmya). Take a microbus from El Dahar to Sharm El Naga for **5–10 EGP** each way. Entrance to Sharm El Naga protected area is **50–80 EGP per person** and includes basic snorkeling from the shore — the reef starts just 20 meters from the beach with excellent coral and fish visibility. Rent a snorkel mask & fins on-site for **50–70 EGP extra**. Grab grilled fish at the small canteen on-site for around **120–180 EGP per person**.

- **Evening:** Return to El Dahar and explore **Sharia Sayyed Korayem** (the old market street). Dinner at **Restaurant El Dahar** or **Abu Ashraf Restaurant** — a local favourite serving kofta platters, grilled chicken, salad, and bread for **80–130 EGP per person**. After dinner, stroll the **Sigala Marina promenade** — free, lively, and perfect for a relaxed first night. Grab a fresh juice from a street cart for **20–30 EGP**.

- 💡 **Local tip:** El Dahar is significantly cheaper than the Sahl Hasheesh or New Hurghada hotel strip. Staying here can cut your daily costs by 40% while giving you a more authentic Egyptian experience.
- ⚠️ **Watch out:** Taxi drivers at the bus station will quote 150–200 EGP for any ride. The correct fare from El Dahar to Sigala is **30–50 EGP** — always negotiate before getting in or use a microbus.

---

**Day 2 — Diving or Snorkeling Boat Trip + Nightlife**

- **Morning:** This is your dedicated water day. Book a **budget group snorkeling boat trip** departing from Hurghada Marina or the small harbour in El Dahar. Local operators like **Sindbad Aqua Club** or smaller independent boats charge **350–500 EGP per person** for a full-day trip (8am–3pm) covering 2–3 reef sites including **Giftun Island** reefs, with snorkel gear, fins, and lunch included. If any of your group wants to try a **discover scuba dive**, add ~**600–800 EGP extra** per person through the same operator — far cheaper than booking through a hotel desk. Be at the harbour by 7:45am.

- **Afternoon:** The boat typically returns by 2:30–3pm. Head back, shower, and relax. Visit the **Hurghada Grand Aquarium** on the New Hurghada road if the group wants a low-energy afternoon — entry is **200–250 EGP per person** and it\'s genuinely impressive with Red Sea species. Alternatively, take a nap on the free **El Dahar public beach** and save the money.

- **Evening:** Tonight is for nightlife. Hurghada has a surprisingly active bar and club scene centred around **Papas Bar (Sigala)** and the **Marina Blvd strip**. Start with drinks at **Papas Bar** — local Sakara or Stella beer costs **80–120 EGP per bottle**, imported drinks around **150–200 EGP**. Move on to **Ministry of Sound Hurghada** or **Hed Kandi Beach Club** — cover charges are typically **200–300 EGP** and usually include one drink. Clubs get going after 11pm and run until 3–4am. Budget total for an evening out: **500–700 EGP per person** including transport back.

- 💡 **Local tip:** Book the snorkeling boat trip the evening before directly at the harbour — you\'ll pay 30–40% less than booking through your hotel or a street tout. Look for boats with a licensed guide (ask to see the licence — legitimate operators carry it).
- ⚠️ **Watch out:** "Free trip" offers on the Marina promenade are never free — they\'re time-share presentations disguised as boat excursions. If anyone approaches promising a complimentary trip, walk away.

---

**Day 3 — Luxor Day Trip (History & Temples) + Farewell Dinner**

- **Morning (early start):** Wake up at 5am for a shared **minibus day trip to Luxor** — the most iconic history excursion from Hurghada. Reputable local operators like **Misr Travel Hurghada** or agencies on **Sharia Sheraton** offer group minibus day trips for **800–1,100 EGP per person**, covering return transport (3-hour drive each way), entrance to the **Valley of the Kings** (including 3 tombs), **Karnak Temple**, **Hatshepsut Temple (Deir el-Bahari)**, and a Nile-side lunch. This is exceptional value for one of the world\'s greatest archaeological sites. Entry fees to Valley of the Kings alone are **360 EGP** — these should be included in the package price so confirm before booking.

- **Afternoon:** You\'ll be in Luxor from roughly 9am–3pm. Spend the morning at the **West Bank** — Valley of the Kings and Hatshepsut Temple. After the included lunch (usually at a local Luxor restaurant near the Nile), visit **Karnak Temple Complex** on the East Bank — the largest ancient religious complex ever built. Walk through the **Avenue of Sphinxes** and the Great Hypostyle Hall. The minibus typically departs Luxor by 3:30–4pm, arriving back in Hurghada by 7–7:30pm.

- **Evening:** Farewell dinner back in Hurghada. Try **Sakia Restaurant** in El Dahar or **Fish Market Restaurant** near the corniche — order grilled Red Sea fish (hammour or sultan ibrahim), mixed mezze, and fresh bread. Expect to pay **200–300 EGP per person** for a proper sit-down meal. Finish the trip with a **shisha session** at a local ahwa (coffeehouse) on El Dahar corniche — shisha costs **60–100 EGP** and tea is **15–25 EGP**. Sit back, watch the Red Sea, and reflect on a well-spent three days.

- 💡 **Local tip:** For the Luxor trip, sit on the left side of the minibus on the way there for the best desert sunrise views over the Eastern Desert — genuinely spectacular around 6–7am.
- ⚠️ **Watch out:** Some "Luxor day trip" packages sold by hotel-lobby agents skip Karnak or reduce temple time significantly to push you toward their affiliated souvenir shops. Book with a street-level agency and get the full itinerary in writing (or photographed) before paying.

---

**💰 Budget Breakdown (per person)**

| Category | EGP | EUR |
|---|---|---|
| Accommodation (3 nights, shared room) | 810–1,200 EGP | ~€15–22 |
| Food (3 days, local restaurants) | 750–1,100 EGP | ~€14–20 |
| Activities & transport | 1,850–2,600 EGP | ~€34–48 |
| **Total estimated** | **3,400–4,900 EGP** | **~€63–91** |

> 📌 *Activities include: snorkeling boat trip, Luxor day trip, aquarium (optional), nightlife evening, and local transport. The Luxor day trip is the largest single cost but represents exceptional value — it\'s worth prioritising.*

> 💱 **Current rate: 1 EUR ≈ 54 EGP** *(April 2026 approximate rate — always check xe.com before travel as the Egyptian pound fluctuates)*

---

**✅ Top 3 Things To Book in Advance**

1. **Luxor Day Trip (Day 3)** — Book 1–2 days ahead minimum, especially in spring high season. Shared minibuses fill quickly. Book in person at an El Dahar agency the day you arrive.
2. **Snorkeling/Diving Boat Trip (Day 2)** — Book the evening before at the harbour directly. Legitimate boats with open spots fill up by 7am on the day.
3. **Budget Accommodation in El Dahar** — Hurghada\'s budget guesthouses are limited in number. Book at least 1 week ahead on Booking.com or contact directly via WhatsApp — many small guesthouses aren\'t on major platforms but have WhatsApp numbers listed on Google Maps.

---

**🚫 Top 3 Scams To Avoid in Hurghada**

1. **The "Friendly Local Guide" on the Corniche** — A well-dressed Egyptian man approaches you, speaks excellent English, and offers to show you around "for free" because he wants to "practise English." He will eventually steer you to a specific shop, boat company, or restaurant where he earns commission — inflating your price by 50–100%. *How to avoid: Politely decline all unsolicited guiding offers, no matter how genuine they seem.*

2. **Taxi Metre Fraud / Price Doubling After the Ride** — You agree on a fare of 40 EGP before getting in. At the destination, the driver claims the price was "per person" or "each way," demanding 120–200 EGP. *How to avoid: Always confirm the total price for all passengers for the complete journey before entering the vehicle. Have the exact amount ready in small bills — handing a large note invites claims of "no change."*

3. **Fake Diving Certification Shortcuts** — Touts near the Marina offer "certified Open Water diver courses" in one day for 1,500–2,000 EGP. A genuine PADI/SSI Open Water course takes 3–4 days minimum. These operations use uncertified instructors, skip safety protocols, and issue fake certificates that won\'t be recognised anywhere. *How to avoid: Only book diving courses with PADI or SSI-registered dive centres — verify the centre\'s registration number at padi.com or divessi.com before paying any deposit.*

---

**📞 Emergency Numbers for Hurghada**

- 🚔 **Tourist Police:** 126
- 🚑 **Ambulance:** 123
- 🏥 **Hurghada International Hospital:** +20 65 354 9773 *(El Salam Street, New Hurghada — English-speaking staff available)*
- 🚓 **General Police:** 122
- 🔥 **Fire:** 180

---

*Itinerary created by **Locali Egypt** — your trusted on-the-ground travel guide. Prices reflect April 2026 local market rates and may vary by ±15% seasonally. Always carry a mix of small EGP notes as many local vendors and microbuses don\'t carry change.*', 'Budget', '69de893104b6c76cca2ee880', '2026-04-14 18:36:33', '2026-04-14 18:36:33', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);

-- ============================================================
-- Table: scam_report
-- ============================================================

CREATE TABLE IF NOT EXISTS `scam_report` (
  `id` VARCHAR(100) NOT NULL,
  `severity` VARCHAR(50) NULL,
  `location_name` VARCHAR(255) NULL,
  `amount_lost` INT NULL,
  `upvotes` INT NULL,
  `city` VARCHAR(100) NULL,
  `latitude` DECIMAL(10,7) NULL,
  `description` TEXT NULL,
  `title` VARCHAR(255) NULL,
  `category` VARCHAR(100) NULL,
  `longitude` DECIMAL(10,7) NULL,
  `status` VARCHAR(50) NULL,
  `created_date` DATETIME NULL,
  `updated_date` DATETIME NULL,
  `created_by_id` VARCHAR(100) NULL,
  `created_by` VARCHAR(255) NULL,
  `is_sample` TINYINT(1) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('medium', 'sdsd', 0, 0, 'sharm-el-sheikh', NULL, 'sdsd', 'google', 'tour', NULL, 'pending', '69e91fdd76638d39aa9aed49', '2026-04-22 19:22:05', '2026-04-22 19:22:05', 'anonymous', 'anonymous', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('medium', 'El Gouna hotel tour desks', 500, 31, 'hurghada', NULL, 'Hotel tour desks in El Gouna charge 40-50% more than booking directly at the marina. A Giftun snorkeling trip costs 800-1,000 EGP at the marina but 1,400-1,600 EGP through the hotel. Always walk to the marina and book direct — same boats, same trips, lower price.', 'Hotel excursion desk 40-50% markup on boat trips', 'tour', NULL, 'verified', '69ded74535023d1685e4570f', '2026-04-15 00:09:41', '2026-04-15 00:09:41', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('low', 'Abu Tig Marina area, El Gouna', 150, 19, 'hurghada', NULL, 'Vendors near Abu Tig Marina sell SIM cards for 300-400 EGP claiming they have \'special tourist packages\'. Official Vodafone and Orange SIM cards with 40GB data cost 250 EGP at official stores in Downtown. Buy only from official telecom stores — ask to see the official store ID.', 'Fake \'local SIM\' sold at inflated price near marina', 'shopping', NULL, 'verified', '69ded74535023d1685e45710', '2026-04-15 00:09:41', '2026-04-15 00:09:41', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('high', 'Abu Tig Marina restaurants, El Gouna', 800, 45, 'hurghada', NULL, 'Some Abu Tig Marina restaurants present menus with prices in EUR or without specifying currency. A pasta dish listed as \'18\' could be 18 EUR (~1,000 EGP) instead of 180 EGP. Always ask \'are these prices in EGP?\' before ordering. If they won\'t confirm, leave.', 'Marina restaurant EUR menu trick', 'restaurant', NULL, 'verified', '69ded74535023d1685e4570d', '2026-04-15 00:09:41', '2026-04-15 00:09:41', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('high', 'Kite Beach / Mangroovy Beach, El Gouna', 0, 38, 'hurghada', NULL, 'Men on Kite Beach offer cheap \'private\' kite lessons without IKO certification. This is dangerous — improper kite training has caused serious accidents. Only book with schools that display their IKO certification. Ask to see the instructor\'s IKO card. Recommended: Kite House, Freeride El Gouna.', 'Uncertified \'kite instructor\' offering cheap lessons', 'tour', NULL, 'verified', '69ded74535023d1685e4570e', '2026-04-15 00:09:41', '2026-04-15 00:09:41', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('medium', 'El Gouna hotel entrances', 350, 28, 'hurghada', NULL, 'Drivers waiting outside El Gouna hotels quote 500-700 EGP for the 30km ride to Hurghada Airport. The correct price is 200-350 EGP for a private car. Always pre-book through your hotel or use the official transfer desk. Ignore drivers who approach you proactively.', 'Tuk-tuk massive overcharge for airport run', 'taxi', NULL, 'verified', '69ded74535023d1685e4570c', '2026-04-15 00:09:41', '2026-04-15 00:09:41', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('high', 'Old Market area and near nightlife venues', 3000, 38, 'hurghada', NULL, 'Men posing as plainclothes police stop tourists and claim to find \'drugs\' in their bag (planted). Demand cash to \'let it go.\' Real Egyptian tourist police wear uniforms and carry official IDs. If approached by plainclothes men, demand to go to the official police station. Do not pay.', 'Fake Police / \'Drug Check\' Extortion', 'other', NULL, 'verified', '69d7d49c12e4eaaa47d2e5ea', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('medium', 'Various roads in Hurghada, especially near resorts', 1500, 103, 'hurghada', NULL, 'Tour guide or driver takes you on an \'extra stop\' at a \'family alabaster workshop\' or \'papyrus museum.\' It\'s actually a shop where they use pressure tactics to sell overpriced items. You won\'t leave easily. Say \'No thank you\' firmly and walk out.', 'Free Trip Then Hard Sell at Papyrus / Perfume Shop', 'tour', NULL, 'verified', '69d7d49c12e4eaaa47d2e5e8', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('medium', 'Marina shops and Dahar bazaar area', 800, 47, 'hurghada', NULL, 'Shop owners claim to sell \'authentic ancient papyrus\' but it\'s actually banana leaf paper painted to look like papyrus. Real papyrus is stiff and doesn\'t fold easily. Banana paper folds and creases. Ask them to fold it — if it folds easily, it\'s fake.', 'Fake Papyrus Scam — Banana Leaf Sold as Real Papyrus', 'shopping', NULL, 'verified', '69d7d49c12e4eaaa47d2e5e5', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('high', 'Hotel lobbies and Marina promenade', 2000, 62, 'hurghada', NULL, 'Man approaches claiming to be from the hotel and offers to exchange money at \'better than bank rate.\' Gives counterfeit EGP notes or short-counts. Never exchange money with individuals outside official banks or exchange bureaus.', 'Hotel Room \'Upgrade\' Money Exchange Scam', 'money_exchange', NULL, 'verified', '69d7d49c12e4eaaa47d2e5e7', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('low', 'Hurghada Marina boat dock', 300, 55, 'hurghada', NULL, 'Book a glass-bottom boat trip but at the dock, staff demand extra for \'mask and snorkel rental\' not mentioned before. Sometimes they demand \'environmental fee\' or \'crew tip\' on top. Ask for EVERYTHING that\'s included in writing before boarding.', 'Glass-Bottom Boat \'Extra Equipment\' Fee', 'tour', NULL, 'verified', '69d7d49c12e4eaaa47d2e5e9', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('medium', 'Beach vendors and small kiosks', 120, 74, 'hurghada', NULL, 'Cheap sunscreen sold at beach vendors and small shops often has a fake SPF number. Tested products claimed SPF50 but performed like SPF5. Buy sunscreen from official pharmacies (Al Ezaby, Seif Pharmacy) only. Especially important for redheads and fair-skinned Europeans.', 'Sunscreen — SPF number is fake', 'shopping', NULL, 'verified', '69d7d49c12e4eaaa47d2e5eb', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('medium', 'Hurghada Airport and Marina taxi stands', 400, 89, 'hurghada', NULL, 'Driver starts the journey then claims the meter is broken and demands 3-5x the fair price at destination. Always agree on a FIXED price before getting in, or use Uber. Never negotiate at the destination — you\'ve already lost.', 'Taxi Meter \'Broken\' Overcharge', 'taxi', NULL, 'verified', '69d7d49c12e4eaaa47d2e5e6', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('medium', 'Sharm El Sheikh International Airport, arrivals exit', 600, 156, 'sharm-el-sheikh', NULL, 'Drivers outside Sharm airport demand 500-800 EGP for the 10-minute Naama Bay drive. Fair price is 100-150 EGP. Use the official taxi desk INSIDE the terminal, not the men who approach you outside. Show them this price guide.', 'Sharm Airport Taxi Overcharge — Demand 800 EGP for Naama Bay', 'taxi', NULL, 'verified', '69d7d49c12e4eaaa47d2e5e0', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('low', 'Various roads between Naama Bay and Old Market', 500, 44, 'sharm-el-sheikh', NULL, 'Tuk-tuk or taxi driver offers a \'scenic route\' and ends up at a carpet or alabaster shop where you get hard-sold. Driver gets a commission from the shop. Tell your driver your exact destination only. If they stop anywhere unplanned, refuse to get out.', 'Carpet Shop Detour by Tuk-Tuk Driver', 'taxi', NULL, 'verified', '69d7d49c12e4eaaa47d2e5e2', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('high', 'Budget dive shops on side streets near Naama Bay', 1500, 81, 'sharm-el-sheikh', NULL, 'Budget dive \'schools\' take payment for PADI Open Water certification (1000-1500 EGP) but only do 1-2 pool sessions then issue a certificate without completing training. This is dangerous and illegal. Only certify with PADI Five Star Centers.', 'Fake Dive Certificate — You Paid, They Don\'t Train', 'tour', NULL, 'verified', '69d7d49c12e4eaaa47d2e5e4', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('high', 'Public beaches, Naama Bay beach front', 800, 92, 'sharm-el-sheikh', NULL, 'Men on the beach claim to offer diving or snorkeling instruction. No license, no safety equipment, no insurance. Tourists have been injured. Only dive with PADI-certified centers. Check the PADI website to verify any dive operator.', 'Unlicensed \'Diving Instructor\' at Beach', 'tour', NULL, 'verified', '69d7d49c12e4eaaa47d2e5e1', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('low', 'Old Market (Sharm El Qadeema) restaurants', 100, 67, 'sharm-el-sheikh', NULL, 'Restaurant gives change for 100 EGP when you paid 200 EGP. Happens quickly and confidently. Count all change immediately and visibly before putting it away. If wrong, say \'Counting error\' loudly — it usually gets corrected.', 'Short-Change at Old Market Restaurants', 'restaurant', NULL, 'verified', '69d7d49c12e4eaaa47d2e5e3', '2026-04-09 16:32:28', '2026-04-09 16:32:28', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('medium', 'Hurghada Airport', 250, 12, 'hurghada', NULL, 'Driver from airport drove in circles to inflate the meter. 20-minute ride took 45 minutes. Was charged 400 EGP for what should cost 150.', 'Taxi driver took the long route', 'taxi', NULL, 'verified', '69c68be623533aadb23e18b0', '2026-03-27 13:53:42', '2026-03-27 13:53:42', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('high', 'Naama Bay Marina', 400, 18, 'sharm-el-sheikh', NULL, 'Booked a snorkeling trip for 200 EGP. Once on the boat, was told 200 was per activity - snorkeling, lunch, and photos each 200. Total 600.', 'Tour price tripled on the boat', 'tour', NULL, 'verified', '69c68be623533aadb23e18b2', '2026-03-27 13:53:42', '2026-03-27 13:53:42', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `scam_report` (`severity`, `location_name`, `amount_lost`, `upvotes`, `city`, `latitude`, `description`, `title`, `category`, `longitude`, `status`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('medium', 'El Dahar Old Town', 200, 8, 'hurghada', NULL, 'Small exchange office in old town gave wrong amount, claiming they already paid the right amount. Always count money immediately.', 'Money exchange shortchanged', 'money_exchange', NULL, 'verified', '69c68be623533aadb23e18b3', '2026-03-27 13:53:42', '2026-03-27 13:53:42', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);

