CREATE TABLE IF NOT EXISTS `service` (
  `id` VARCHAR(100) NOT NULL,
  `city` VARCHAR(100) NULL,
  `main_image` TEXT NULL,
  `latitude` DECIMAL(10,7) NULL,
  `description` TEXT NULL,
  `review_count` INT NULL,
  `price_range` VARCHAR(50) NULL,
  `description_ru` TEXT NULL,
  `photos` TEXT NULL,
  `description_de` TEXT NULL,
  `discount_claims` INT NULL,
  `name_ru` TEXT NULL,
  `name_de` TEXT NULL,
  `avg_rating` DECIMAL(3,2) NULL,
  `longitude` DECIMAL(10,7) NULL,
  `website` TEXT NULL,
  `scam_score` INT NULL,
  `subscription_tier` VARCHAR(50) NULL,
  `address` TEXT NULL,
  `is_verified` TINYINT(1) NULL,
  `discount_views` INT NULL,
  `tags` TEXT NULL,
  `phone` VARCHAR(100) NULL,
  `name` VARCHAR(255) NULL,
  `commission_rate` INT NULL,
  `category` VARCHAR(100) NULL,
  `is_featured` TINYINT(1) NULL,
  `created_date` DATETIME NULL,
  `updated_date` DATETIME NULL,
  `created_by_id` VARCHAR(100) NULL,
  `created_by` VARCHAR(255) NULL,
  `is_sample` TINYINT(1) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

