INSERT INTO `service` (`city`, `main_image`, `latitude`, `description`, `review_count`, `price_range`, `description_ru`, `photos`, `description_de`, `discount_claims`, `name_ru`, `name_de`, `avg_rating`, `longitude`, `website`, `scam_score`, `subscription_tier`, `address`, `is_verified`, `discount_views`, `tags`, `phone`, `name`, `commission_rate`, `category`, `is_featured`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('el-gouna', 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/6d279909c_DowntownRestaurantBarElGounalocalhangout.jpg', NULL, 'The real El Gouna social venue for expats and long-stays. Open from breakfast to 1am. Good local-price Egyptian food alongside cocktails. The patio fills with locals by 7pm. Much cheaper than Marina restaurants.', 0, 'budget', NULL, '["https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/0f9e3f393_DowntownRestaurantBarElGounalocalhangout.jpg"]', NULL, 0, NULL, NULL, 0.0, NULL, NULL, 0, 'none', NULL, 1, 0, '["el-gouna","local","expat","bar"]', NULL, 'Downtown Restaurant & Bar (El Gouna local hangout)', 0, 'restaurant', 0, '69ded9c092d624041ba5e683', '2026-04-15 00:20:16', '2026-04-16 02:30:15', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
