INSERT INTO `service` (`city`, `main_image`, `latitude`, `description`, `review_count`, `price_range`, `description_ru`, `photos`, `description_de`, `discount_claims`, `name_ru`, `name_de`, `avg_rating`, `longitude`, `website`, `scam_score`, `subscription_tier`, `address`, `is_verified`, `discount_views`, `tags`, `phone`, `name`, `commission_rate`, `category`, `is_featured`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('el-gouna', 'https://base44.app/api/apps/69c689e2d4aa000453950c3f/files/mp/public/69c689e2d4aa000453950c3f/8faed1f60_ElGounaKayaktoUninhabitedIsland.webp', NULL, 'Paddle a kayak from Mangroovy Beach to the small uninhabited lagoon island 20 minutes south. Take a picnic. Completely deserted most days. White sand, calm water, no sunbed attendants. The El Gouna experience without the price tag.', 0, 'budget', NULL, '[]', NULL, 0, NULL, NULL, 0.0, NULL, NULL, 0, 'none', NULL, 0, 0, '["el-gouna","kayak","island","picnic"]', NULL, 'El Gouna Kayak to Uninhabited Island', 0, 'activities', 0, '69ded9c092d624041ba5e67f', '2026-04-15 00:20:16', '2026-04-16 02:30:14', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
