INSERT INTO `service` (`city`, `main_image`, `latitude`, `description`, `review_count`, `price_range`, `description_ru`, `photos`, `description_de`, `discount_claims`, `name_ru`, `name_de`, `avg_rating`, `longitude`, `website`, `scam_score`, `subscription_tier`, `address`, `is_verified`, `discount_views`, `tags`, `phone`, `name`, `commission_rate`, `category`, `is_featured`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('sharm-el-sheikh', 'https://images.pexels.com/photos/14137300/pexels-photo-14137300.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', NULL, 'BESTSELLER in Sharm El Sheikh (4,283 reviews, 4.9 rating). 5-hour evening safari combining ATV quad biking in the Sinai desert, camel ride at sunset, traditional Bedouin tent BBQ dinner, and live cultural show. Hotel pickup included. Price: from €20.50/person (~EGP 1,100).', 4283, 'moderate', NULL, '[]', NULL, 0, NULL, NULL, 4.9, NULL, NULL, 8, 'none', 'Sinai Desert, Sharm El Sheikh (hotel pickup included)', 1, 0, '["Quad Biking","Camel Ride","BBQ Dinner","Desert","Bedouin Experience","Bestseller"]', NULL, 'ATV Desert Safari + Camel + Bedouin BBQ — Sharm', 0, 'activities', 0, '69d6bdbd6d4db8dc94ed9dce', '2026-04-08 20:42:37', '2026-04-23 17:36:49', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
