-- ============================================================
-- Table: tourist_story
-- ============================================================

CREATE TABLE IF NOT EXISTS `tourist_story` (
  `id` VARCHAR(100) NOT NULL,
  `story_type` VARCHAR(100) NULL,
  `author_name` VARCHAR(100) NULL,
  `upvotes` INT NULL,
  `city` VARCHAR(100) NULL,
  `how_handled` TEXT NULL,
  `what_happened` TEXT NULL,
  `title` VARCHAR(255) NULL,
  `is_positive` TINYINT(1) NULL,
  `is_verified` TINYINT(1) NULL,
  `lesson_learned` TEXT NULL,
  `tourist_nationality` VARCHAR(100) NULL,
  `created_date` DATETIME NULL,
  `updated_date` DATETIME NULL,
  `created_by_id` VARCHAR(100) NULL,
  `created_by` VARCHAR(255) NULL,
  `is_sample` TINYINT(1) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `tourist_story` (`story_type`, `author_name`, `upvotes`, `city`, `how_handled`, `what_happened`, `title`, `is_positive`, `is_verified`, `lesson_learned`, `tourist_nationality`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('helpful_local', 'Natasha V.', 445, 'hurghada', 'I called the hotel reception who immediately called a doctor to our room (200 EGP, took 20 minutes). Doctor prescribed oral rehydration salts and told us which pharmacy was open. We went to Al Ezaby Pharmacy at Senzo Mall (open until midnight). Daughter was better within 24 hours. Everyone was kind and professional.', 'My 7-year-old daughter got severe gastroenteritis on day 2 of our holiday. She was dehydrated and I didn\'t know where to go at 2am. I was scared — you read horror stories about hospitals in Egypt.', 'My child got a stomach bug — how Egypt\'s hospitals really work', 1, 1, 'Don\'t panic. Hotel doctors are available 24/7 and are often the fastest option. Al Ezaby pharmacy chain is reliable and they understand medical Russian and English. Keep rehydration sachets in your bag — stomach upsets are common in summer.', 'Russian', '69d7d52c12e4eaaa47d2e63e', '2026-04-09 16:34:52', '2026-04-09 16:34:52', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `tourist_story` (`story_type`, `author_name`, `upvotes`, `city`, `how_handled`, `what_happened`, `title`, `is_positive`, `is_verified`, `lesson_learned`, `tourist_nationality`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('scam_avoided', 'Sarah M.', 234, 'sharm-el-sheikh', 'I politely declined, walked through the glass doors to the official taxi stand, showed the officer the price guide on my phone, and got a legitimate taxi for 120 EGP. The driver was totally normal and professional.', 'I\'d just landed at Sharm Airport and was exhausted from a 5-hour flight. A man in a blue jacket approached me near the baggage carousel (before I even got outside) claiming to be from \'official taxis.\' He quoted 600 EGP for Naama Bay. I\'d read the Locali Egypt price guide and knew the fair price was 100-150 EGP.', 'How I avoided a 600 EGP taxi scam at Sharm Airport', 1, 1, 'Anyone who approaches you BEFORE you exit the terminal is not official. Always walk to the marked taxi stand outside. Have the price guide screenshot saved on your phone before you land.', 'British', '69d7d52c12e4eaaa47d2e63a', '2026-04-09 16:34:52', '2026-04-09 16:34:52', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);
INSERT INTO `tourist_story` (`story_type`, `author_name`, `upvotes`, `city`, `how_handled`, `what_happened`, `title`, `is_positive`, `is_verified`, `lesson_learned`, `tourist_nationality`, `id`, `created_date`, `updated_date`, `created_by_id`, `created_by`, `is_sample`) VALUES ('great_experience', 'Michal K.', 267, 'hurghada', 'Booked directly with the dive center (not through the hotel). Hotel wanted 1,800 EGP for the same trip — dive center charged 1,200 EGP direct. Better quality, 33% cheaper.', 'I\'d been diving in Thailand and the Maldives before. Nothing compared to Giftun Island in Hurghada. 30-meter visibility, walls of coral, Napoleon wrasse, huge turtles, schools of barracuda. Jasmin Dive Center had maximum 6 people per guide and the safety briefing was the most thorough I\'ve experienced anywhere.', 'Red Sea diving — most incredible thing I\'ve ever seen', 1, 1, 'Always book activities directly, never through your hotel. Hotel commission is 30-50%. Walk 200m to the actual operator and save significantly while getting better service.', 'Polish', '69d7d52c12e4eaaa47d2e63d', '2026-04-09 16:34:52', '2026-04-09 16:34:52', '69c689e2d4aa000453950c40', 'moa855914@gmail.com', 0);

